<?php $items=cart_items($store); ?><section class="page-hero"><div class="container narrow"><p class="eyebrow">Basket</p><h1>Your basket</h1><p>Review your items before continuing to secure checkout.</p></div></section><section class="section"><div class="container"><?php if($items===[]):?><div class="empty panel"><h2>Your basket is empty.</h2><p><a class="button primary" href="/products">Browse products</a></p></div><?php else:?><div class="panel"><table class="cart-table"><thead><tr><th>Product</th><th>Unit price</th><th>Quantity</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($items as $item):$product=$item['product'];?><tr><td><a href="/products/<?=e($product['slug'])?>"><?=e($product['name'])?></a></td><td><?=e(money((int)$product['price_pence'],$store))?></td><td><form class="cart-actions" method="post" action="/cart"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="slug" value="<?=e($product['slug'])?>"><input class="quantity-input" name="quantity" type="number" min="0" max="<?=e((string)$product['stock'])?>" value="<?=e((string)$item['quantity'])?>"><button class="button secondary" type="submit">Update</button></form></td><td><?=e(money((int)$item['line_total'],$store))?></td><td><form method="post" action="/cart"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="slug" value="<?=e($product['slug'])?>"><button class="button secondary" type="submit">Remove</button></form></td></tr><?php endforeach;?></tbody></table><div class="total-row"><span>Total</span><span><?=e(money(cart_total($store),$store))?></span></div><div class="actions"><a class="button secondary" href="/products">Continue shopping</a><a class="button primary" href="/checkout">Checkout</a></div></div><?php endif;?></div></section>
